ESP32: loop() uden at blokere


src/main.cpp (uddrag)

void loop() {
  unsigned long nu = millis();
  if (mqtt.connected()) {
    mqtt.loop();                                   // ping og modtagelse
  } else if (WiFi.status() == WL_CONNECTED && nu - sidsteForsoeg &gt;= 5000) {
    sidsteForsoeg = nu;
    mqtt.connect(klientId);                        // ét forsøg, ingen while
  }
  if (mqtt.connected() && nu - sidsteSend &gt;= 5000) {
    sidsteSend = nu;
    sendMaaling();                                 // snprintf + mqtt.publish
  }
}

