CA-certifikatet lægges i en header-fil som en tekststreng. R"PEM( ... )PEM" er en rå streng i C++: alt mellem parenteserne kommer med, også linjeskift, så du kan sætte filens indhold direkte ind.


include/ca_cert.h

// Skolens MQTT-CA (ca.crt). Certifikatet er offentligt, så filen må committes.
#pragma once

const char CA_CERT[] = R"PEM(
Erstat disse to linjer med hele indholdet af ca.crt,
fra -----BEGIN CERTIFICATE----- til og med -----END CERTIFICATE-----
)PEM";



src/main.cpp

#include &lt;Arduino.h&gt;
#include &lt;WiFi.h&gt;
#include &lt;WiFiClientSecure.h&gt;
#include &lt;PubSubClient.h&gt;
#include "secrets.h"   // WIFI_SSID, WIFI_PASSWORD, MQTT_USER, MQTT_PASSWORD
#include "ca_cert.h"   // CA_CERT

// Konfiguration
const char* MQTT_HOST = "wilsons.local";       // skal stå i brokerens certifikat
const uint16_t MQTT_PORT = 8883;               // TLS + login
const unsigned long WIFI_TIMEOUT_MS  = 20000;  // max ventetid på WiFi i setup()
const unsigned long MQTT_FORSOEG_MS  = 5000;   // pause mellem forsøg på at forbinde
const unsigned long SEND_INTERVAL_MS = 10000;  // hvor tit der sendes en måling

WiFiClientSecure tlsKlient;      // krypteret forbindelse
PubSubClient mqtt(tlsKlient);    // MQTT oven på den krypterede forbindelse

String sendTopic;     // elever/&lt;brugernavn&gt;/status
String modtagTopic;   // elever/&lt;brugernavn&gt;/kommando
unsigned long sidsteForsoeg = 0;
unsigned long sidsteSend = 0;

// Som på WiFi-siden: vent højst timeoutMs
bool forbindWiFi(unsigned long timeoutMs) {
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  Serial.printf("Forbinder til WiFi %s", WIFI_SSID);
  unsigned long start = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - start &lt; timeoutMs) {
    delay(500);  // OK her: setup() har ikke andet at lave endnu
    Serial.print(".");
  }
  Serial.println();
  return WiFi.status() == WL_CONNECTED;
}

// Kaldes af mqtt.loop(), når der kommer en besked på et topic, vi abonnerer på
void modtag(char* topic, byte* payload, unsigned int laengde) {
  Serial.printf("Modtaget på %s: ", topic);
  Serial.write(payload, laengde);  // payload er ikke en C-streng med \0 til sidst
  Serial.println();
}

bool forbindMqtt() {
  // Client-id skal være unikt på brokeren. De sidste tre bytes af MAC-adressen er forskellige fra kort til kort.
  String klientId = String(MQTT_USER) + "-" + String((uint32_t)(ESP.getEfuseMac() &gt;&gt; 24), HEX);

  Serial.printf("Forbinder til %s:%u ... ", MQTT_HOST, MQTT_PORT);
  if (mqtt.connect(klientId.c_str(), MQTT_USER, MQTT_PASSWORD)) {
    Serial.println("OK");
    // Abonnér efter hver forbindelse, ligesom on_connect i Python
    mqtt.subscribe(modtagTopic.c_str());
    return true;
  }

  // Skriv både MQTT-status og en eventuel TLS-fejl ud; det er de bedste spor
  char tlsTekst[100] = "";
  int tlsFejl = tlsKlient.lastError(tlsTekst, sizeof(tlsTekst));
  Serial.printf("fejl, rc=%d", mqtt.state());
  if (tlsFejl != 0) {
    Serial.printf(", TLS: %s", tlsTekst);
  }
  Serial.println();
  return false;
}

void sendMaaling() {
  char payload[100];
  snprintf(payload, sizeof(payload), "{\"uptime_s\":%lu,\"rssi\":%d}",
           millis() / 1000, WiFi.RSSI());
  bool ok = mqtt.publish(sendTopic.c_str(), payload);
  Serial.printf("%s %s %s\n", ok ? "Sendt" : "IKKE sendt", sendTopic.c_str(), payload);
}

void setup() {
  Serial.begin(115200);

  // Topics bygges af brugernavnet, så de altid passer med ACL'en
  sendTopic   = String("elever/") + MQTT_USER + "/status";
  modtagTopic = String("elever/") + MQTT_USER + "/kommando";

  if (!forbindWiFi(WIFI_TIMEOUT_MS)) {
    Serial.printf("Ingen WiFi (status %d). ESP32 prøver selv igen.\n", WiFi.status());
  }

  tlsKlient.setCACert(CA_CERT);          // tjek brokerens certifikat mod skolens CA
  mqtt.setServer(MQTT_HOST, MQTT_PORT);  // navnet bruges også til at tjekke certifikatet
  mqtt.setCallback(modtag);
}

void loop() {
  unsigned long nu = millis();

  if (mqtt.connected()) {
    mqtt.loop();  // modtager beskeder og holder forbindelsen i live

    if (nu - sidsteSend &gt;= SEND_INTERVAL_MS) {
      sidsteSend = nu;
      sendMaaling();
    }
  } else if (WiFi.status() == WL_CONNECTED && nu - sidsteForsoeg &gt;= MQTT_FORSOEG_MS) {
    // Forbind (igen) med fast interval, så loop() ikke hænger i en løkke
    sidsteForsoeg = nu;
    forbindMqtt();
  }

  // Her kan programmet læse sensorer og knapper
}


Kopiér secrets_eksempel.h til secrets.h, og udfyld den. Upload og åbn Serial Monitor. Efter WiFi skulle der stå Forbinder til wilsons.local:8883 ... OK og derefter en Sendt-linje hvert 10. sekund. Find dine beskeder i weblog’en under elever/&lt;brugernavn&gt;/status.jsonl.

Sådan virker det:

mqtt.setServer() får navnet, ikke IP-adressen. WiFiClientSecure bruger navnet både til at finde brokeren og til at tjekke, at navnet står i brokerens certifikat.
mqtt.connect() laver først TLS-forbindelsen og logger derefter ind. TLS-håndtrykket kræver en del regnekraft, så kaldet blokerer i et par sekunder. Derfor forsøges der kun hvert 5. sekund.
mqtt.loop() skal kaldes ofte. Den modtager beskeder (og kalder modtag()), og den sender et livstegn til brokeren, så forbindelsen ikke bliver lukket.
Topics bygges af MQTT_USER, så du ikke kommer til at skrive uden for din egen mappe.


Prøv at sende en besked til ESP32 fra din bærbare:
mosquitto_pub -h wilsons.local -p 8883 --cafile ca.crt \
  -u &lt;brugernavn&gt; -P &lt;kode&gt; -t elever/&lt;brugernavn&gt;/kommando -m "Hej ESP32"

Eksempel: læs, skriv og tilføj
Programmet tæller, hvor mange gange ESP32 er startet. Tallet ligger i /antal.txt, som overskrives ved hver opstart. Samtidig tilføjes en linje til /log.txt. Til sidst listes filerne, og pladsen vises. Alt sker i setup(), så tryk på EN for at køre det igen.


platformio.ini

[env:esp32doit-devkit-v1]
platform = espressif32@8.0.0
board = esp32doit-devkit-v1
framework = arduino
monitor_speed = 115200
board_build.filesystem = littlefs



src/main.cpp

#include &lt;Arduino.h&gt;
#include &lt;LittleFS.h&gt;

// Konfiguration
const char *ANTAL_FIL = "/antal.txt";  // antal opstarter, overskrives hver gang
const char *LOG_FIL = "/log.txt";      // én linje pr. opstart, vokser

// Læser antal opstarter. Giver 0, hvis filen ikke findes endnu.
int laesAntal() {
  if (!LittleFS.exists(ANTAL_FIL)) {
    return 0;
  }
  File fil = LittleFS.open(ANTAL_FIL, FILE_READ);
  if (!fil) {
    return 0;
  }
  // Tallet er gemt med et linjeskift efter, så readStringUntil stopper der
  String tekst = fil.readStringUntil('\n');
  fil.close();
  return tekst.toInt();
}

// Overskriver filen med det nye tal
void skrivAntal(int antal) {
  File fil = LittleFS.open(ANTAL_FIL, FILE_WRITE);  // sletter det gamle indhold
  if (!fil) {
    Serial.println("Kunne ikke skrive antal");
    return;
  }
  fil.println(antal);
  fil.close();  // først nu er tallet sikkert gemt
}

// Tilføjer en linje til sidst i filen
void tilfoejLinje(const char *sti, const String &linje) {
  File fil = LittleFS.open(sti, FILE_APPEND);  // opretter filen, hvis den mangler
  if (!fil) {
    Serial.printf("Kunne ikke åbne %s\n", sti);
    return;
  }
  fil.println(linje);
  fil.close();
}

// Skriver hele filens indhold i Serial Monitor
void udskrivFil(const char *sti) {
  File fil = LittleFS.open(sti, FILE_READ);
  if (!fil) {
    Serial.printf("%s findes ikke\n", sti);
    return;
  }
  Serial.printf("--- %s (%u bytes) ---\n", sti, (unsigned)fil.size());
  while (fil.available()) {
    Serial.write(fil.read());
  }
  fil.close();
}

// Lister filerne i en mappe med deres størrelse
void listFiler(const char *mappe) {
  File rod = LittleFS.open(mappe);
  if (!rod || !rod.isDirectory()) {
    Serial.printf("%s er ikke en mappe\n", mappe);
    return;
  }
  Serial.printf("--- Filer i %s ---\n", mappe);
  File fil = rod.openNextFile();
  while (fil) {
    Serial.printf("%-20s %6u bytes\n", fil.name(), (unsigned)fil.size());
    fil = rod.openNextFile();
  }
}

// Viser, hvor meget af filsystemet der er brugt
void visPlads() {
  size_t total = LittleFS.totalBytes();
  size_t brugt = LittleFS.usedBytes();
  Serial.printf("Plads: %u bytes i alt, %u brugt, %u ledig\n",
                (unsigned)total, (unsigned)brugt, (unsigned)(total - brugt));
}

void setup() {
  Serial.begin(115200);

  // true: formatér, hvis partitionen ikke kan monteres (fx første gang)
  if (!LittleFS.begin(true)) {
    Serial.println("LittleFS kunne ikke monteres");
    return;
  }

  int antal = laesAntal() + 1;
  skrivAntal(antal);
  tilfoejLinje(LOG_FIL, "Opstart nr. " + String(antal));

  udskrivFil(LOG_FIL);
  listFiler("/");
  visPlads();
}

void loop() {
}

Efter tre opstarter skal Serial Monitor vise noget i retning af:
--- /log.txt (45 bytes) ---
Opstart nr. 1
Opstart nr. 2
Opstart nr. 3
--- Filer i / ---
antal.txt                 3 bytes
log.txt                  45 bytes
Plads: 1441792 bytes i alt, 8192 brugt, 1433600 ledig
name() giver kun filnavnet uden mappe, fx log.txt. Tallene for pladsen afhænger af partitionen. Selv et tomt filsystem bruger 8192 bytes (2 blokke à 4 KB) til LittleFS’ egen mappe-information. Meget små filer gemmes direkte i den, så de ikke bruger flere blokke. Først når en fil vokser, får den sine egne blokke på 4 KB.

println() afslutter linjen med \r\n. Derfor er hver linje i loggen 15 bytes og ikke 14.

Eksempel: filer fra data/-mappen
Nogle gange skal en fil ligge på ESP32 fra start, fx en konfigurationsfil eller en webside. Dem lægger du i en mappe, der hedder data, ved siden af src:
mit_projekt/
├── data/
│   └── hilsen.txt
├── src/
│   └── main.cpp
└── platformio.ini

Sådan kommer filerne over på ESP32:

Luk Serial Monitor, så porten er fri.
Klik på PlatformIO-ikonet i venstre side.
Under Project Tasks → esp32doit-devkit-v1 → Platform, klik Upload Filesystem Image.

PlatformIO laver et LittleFS-image af hele data/-mappen (med værktøjet mklittlefs) og skriver det til filsystem-partitionen. Fra kommandolinjen hedder det pio run --target uploadfs. Der findes også Build Filesystem Image, der kun laver imaget uden at uploade.








AdvarselUpload Filesystem Image overskriver alt



Imaget erstatter hele filsystemet. Filer, som programmet selv har skrevet på ESP32, fx en cache med målinger, bliver slettet. Har du glemt board_build.filesystem = littlefs, bliver imaget et SPIFFS-image, som LittleFS ikke kan læse, og så formaterer begin(true) partitionen, og filerne fra data/ er væk.



